0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline uint32_t ld32(const uint8_t *p) {
    return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|(uint32_t)p[3];
}

static void compress(uint32_t s[8], const uint8_t *block) {
    uint32_t w[64];
    for (int i=0;i<16;i++) w[i]=ld32(block+4*i);
    for (int i=16;i<64;i++) {
        uint32_t s0 = ROTR(w[i-15],7)^ROTR(w[i-15],18)^(w[i-15]>>3);
        uint32_t s1 = ROTR(w[i-2],17)^ROTR(w[i-2],19)^(w[i-2]>>10);
        w[i]=w[i-16]+s0+w[i-7]+s1;
    }
    uint32_t a=s[0],b=s[1],c=s[2],d=s[3],e=s[4],f=s[5],g=s[6],h=s[7];
    for (int i=0;i<64;i++) {
        uint32_t t1 = h + S1(e) + CH(e,f,g) + K[i] + w[i];
        uint32_t t2 = S0(a) + MAJ(a,b,c);
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    s[0]+=a; s[1]+=b; s[2]+=c; s[3]+=d; s[4]+=e; s[5]+=f; s[6]+=g; s[7]+=h;
}

void sha256(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t s[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                     0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t i;
    for (i=0; i+64<=len; i+=64) compress(s, data+i);
    uint8_t buf[128];
    size_t rem = len - i;
    memcpy(buf, data+i, rem);
    buf[rem]=0x80;
    size_t padlen;
    if (rem<56) { memset(buf+rem+1,0,56-rem-1); padlen=64; }
    else { memset(buf+rem+1,0,64-rem-1); padlen=128; }
    uint64_t bitlen=(uint64_t)len*8;
    for (int j=0;j<8;j++) buf[padlen-1-j]=(uint8_t)(bitlen>>(8*j));
    compress(s, buf);
    if (padlen==128) compress(s, buf+64);
    for (int j=0;j<8;j++) {
        out[4*j]=(uint8_t)(s[j]>>24); out[4*j+1]=(uint8_t)(s[j]>>16);
        out[4*j+2]=(uint8_t)(s[j]>>8); out[4*j+3]=(uint8_t)(s[j]);
    }
}
